"""Build the ASTER evidence synthesis from the published CPU tables."""
import json, os
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "reports/aster_synthesis_20261106"
DATA = ROOT / "results/aster_synthesis_20261106"
def read(name):
    return json.loads((DATA / name).read_text(encoding="utf-8"))
def write(path, content):
    p = ROOT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content.strip()+"\n", encoding="utf-8")
def link(path, label="\u8bc1\u636e"):
    return "["+label+"]("+os.path.relpath(ROOT/path, OUT).replace(os.sep,"/")+")"
def pct(x):
    return f"{100*x:.2f}%"
def table(headers, rows):
    return "\n".join(["| "+" | ".join(headers)+" |", "| "+" | ".join(["---"]*len(headers))+" |"]+["| "+" | ".join(map(str,r))+" |" for r in rows])
MAIN = read("main_comparison.json")
PATHS = read("autonomous_paths.json")
HIST = read("historical_comparison.json")
MECH = read("mechanism_chain.json")
SOURCES = read("history_sources.json")
