ORDER = ["full","aster","soft_angle","global_mean","same_fact","direct_reference","calibrated_full"]
def main_table(split):
    rows=[]
    for method in ORDER:
        r=next(x for x in MAIN if x["split"]==split and x["method"]==method)
        rows.append([LABELS[method]]+[pct(r["PA_"+k]) for k in "APCF"]+[pct(r["macro_PA"]),f'{r["correct"]}/{r["inputs"]}',f'{r["corrected"]}/{r["new_errors"]}'])
    return table(["\u65b9\u6cd5","A","P","C","F","\u56db\u7c7b\u5b8f\u5e73\u5747","\u8f93\u5165\u6b63\u786e\u6570","\u7ea0\u6b63\uff0f\u65b0\u589e\u9519\u8bef"],rows)
def paths_table(scope):
    rows=[]
    for method in ["full","aster","soft_angle","direct","best_output","semantic"]:
        r=next(x for x in PATHS if x["scope"]==scope and x["method"]==method)
        rows.append([LABELS[method],f'{r["numerator"]}/{r["denominator"]}',pct(r["rate"]),f'{r["corrected"]}/{r["new_errors"]}',r["unavailable_inputs"],r["technical_failures"]])
    return table(["\u65b9\u6cd5","\u8def\u5f84\u6b63\u786e\u6570","\u6b63\u786e\u7387","\u7ea0\u6b63\uff0f\u65b0\u589e\u9519\u8bef","\u8f93\u5165\u7f3a\u5931","\u6280\u672f\u5931\u8d25"],rows)
